class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2 != 0:
            return False
        target = total // 2
        dp = set([0])
        for n in nums:
            next_dp = set()
            for t in dp:
                if t + n == target:
                    return True
                if t + n < target:
                    next_dp.add(t + n)
                next_dp.add(t)
            dp = next_dp
        return target in dp

reference_solution.javascript:
function canPartition(nums) {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % 2 !== 0) return false;
    const target = total / 2;
    let dp = new Set([0]);
    for (const n of nums) {
        const nextDp = new Set();
        for (const t of dp) {
            if (t + n === target) return true;
            if (t + n < target) nextDp.add(t + n);
            nextDp.add(t);
        }
        dp = nextDp;
    }
    return dp.has(target);
}
